//! Dedicated LUKS key-wrapping payloads.
//!
//! A disk key is 32 random bytes generated by the setup tool. The phone wraps
//! those bytes with a biometric-gated AES key whose alias is reserved for
//! LUKS. ECDSA signatures never become key material.

use crate::cbor::{Reader, Writer};
use crate::{bytes_equal, check_text, ProtocolError, Result, MAX_APPLICATION_PAYLOAD_BYTES};

pub const OPERATION_ENROLL: &str = "luks.enroll";
pub const OPERATION_UNLOCK: &str = "luks.unlock";
pub const LUKS_SCHEMA: u64 = 1;
pub const DISK_KEY_LEN: usize = 32;
pub const VOLUME_BINDING_LEN: usize = 32;
pub const MAX_WRAPPER_BYTES: usize = 512;

const ENROLL_REQUEST_FIELDS: u64 = 5;
const ENROLL_RESPONSE_FIELDS: u64 = 3;
const UNLOCK_REQUEST_FIELDS: u64 = 6;
const UNLOCK_RESPONSE_FIELDS: u64 = 2;
const WRAPPED_KEY_FIELDS: u64 = 4;
const MAX_NAME_UNITS: usize = 255;
const MAX_ID_UNITS: usize = 64;

fn wipe(buffer: &mut [u8]) {
    for byte in buffer.iter_mut() {
        unsafe { core::ptr::write_volatile(byte, 0) };
    }
    core::sync::atomic::compiler_fence(core::sync::atomic::Ordering::SeqCst);
}

#[derive(Clone, PartialEq, Eq)]
pub struct EnrollRequest {
    pub verifier_name: String,
    pub volume_name: String,
    pub volume_binding: [u8; VOLUME_BINDING_LEN],
    pub disk_key: Vec<u8>,
}

impl Drop for EnrollRequest {
    fn drop(&mut self) {
        wipe(&mut self.disk_key);
    }
}

impl EnrollRequest {
    pub fn validate(&self) -> Result<()> {
        names(&self.verifier_name, &self.volume_name)?;
        key(&self.disk_key)
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut writer = Writer::new();
        writer.array(ENROLL_REQUEST_FIELDS);
        writer.uint(LUKS_SCHEMA);
        writer.text(&self.verifier_name);
        writer.text(&self.volume_name);
        writer.bytes(&self.volume_binding);
        writer.bytes(&self.disk_key);
        writer.into_bytes()
    }

    pub fn decode(payload: &[u8]) -> Result<Self> {
        let mut reader = open(payload, ENROLL_REQUEST_FIELDS)?;
        let value = Self {
            verifier_name: reader.text()?.to_owned(),
            volume_name: reader.text()?.to_owned(),
            volume_binding: fixed("volumeBinding", reader.bytes()?)?,
            disk_key: reader.bytes()?.to_vec(),
        };
        finish(reader, &value.encode(), payload)?;
        value.validate()?;
        Ok(value)
    }
}

#[derive(Clone, PartialEq, Eq)]
pub struct EnrollResponse {
    pub credential_id: String,
    pub wrapper: Vec<u8>,
}

impl EnrollResponse {
    pub fn validate(&self) -> Result<()> {
        check_text("credentialId", &self.credential_id, MAX_ID_UNITS)?;
        wrapper(&self.wrapper)
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut writer = Writer::new();
        writer.array(ENROLL_RESPONSE_FIELDS);
        writer.uint(LUKS_SCHEMA);
        writer.text(&self.credential_id);
        writer.bytes(&self.wrapper);
        writer.into_bytes()
    }

    pub fn decode(payload: &[u8]) -> Result<Self> {
        let mut reader = open(payload, ENROLL_RESPONSE_FIELDS)?;
        let value = Self {
            credential_id: reader.text()?.to_owned(),
            wrapper: reader.bytes()?.to_vec(),
        };
        finish(reader, &value.encode(), payload)?;
        value.validate()?;
        Ok(value)
    }
}

