/// Public data persisted in the initrd configuration.
#[derive(Clone, PartialEq, Eq)]
pub struct WrappedVolumeKey {
    pub volume_binding: [u8; VOLUME_BINDING_LEN],
    pub credential_id: String,
    pub wrapper: Vec<u8>,
}

impl WrappedVolumeKey {
    pub fn validate(&self) -> Result<()> {
        check_text("credentialId", &self.credential_id, MAX_ID_UNITS)?;
        wrapper(&self.wrapper)
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut writer = Writer::new();
        writer.array(WRAPPED_KEY_FIELDS);
        writer.uint(LUKS_SCHEMA);
        writer.bytes(&self.volume_binding);
        writer.text(&self.credential_id);
        writer.bytes(&self.wrapper);
        writer.into_bytes()
    }

    pub fn decode(payload: &[u8]) -> Result<Self> {
        let mut reader = open(payload, WRAPPED_KEY_FIELDS)?;
        let value = Self {
            volume_binding: fixed("volumeBinding", reader.bytes()?)?,
            credential_id: reader.text()?.to_owned(),
            wrapper: reader.bytes()?.to_vec(),
        };
        finish(reader, &value.encode(), payload)?;
        value.validate()?;
        Ok(value)
    }
}

fn names(verifier: &str, volume: &str) -> Result<()> {
    check_text("verifierName", verifier, MAX_NAME_UNITS)?;
    check_text("volumeName", volume, MAX_NAME_UNITS)
}

fn key(value: &[u8]) -> Result<()> {
    if value.len() != DISK_KEY_LEN {
        return Err(ProtocolError::FieldLength {
            field: "diskKey",
            expected: DISK_KEY_LEN,
            actual: value.len(),
        });
    }
    Ok(())
}

fn wrapper(value: &[u8]) -> Result<()> {
    if value.is_empty() || value.len() > MAX_WRAPPER_BYTES {
        return Err(ProtocolError::PayloadSize(value.len()));
    }
    Ok(())
}

fn open(payload: &[u8], fields: u64) -> Result<Reader<'_>> {
    if payload.is_empty() || payload.len() > MAX_APPLICATION_PAYLOAD_BYTES {
        return Err(ProtocolError::PayloadSize(payload.len()));
    }
    let mut reader = Reader::new(payload);
    let actual = reader.array()?;
    if actual != fields {
        return Err(ProtocolError::FrameShape {
            expected: fields,
            actual,
        });
    }
    let schema = reader.uint()?;
    if schema != LUKS_SCHEMA {
        return Err(ProtocolError::UnsupportedVersion(schema));
    }
    Ok(reader)
}

fn finish(reader: Reader<'_>, encoded: &[u8], input: &[u8]) -> Result<()> {
    reader.finish()?;
    if !bytes_equal(encoded, input) {
        return Err(ProtocolError::NotCanonical);
    }
    Ok(())
}

fn fixed<const N: usize>(field: &'static str, value: &[u8]) -> Result<[u8; N]> {
    value.try_into().map_err(|_| ProtocolError::FieldLength {
        field,
        expected: N,
        actual: value.len(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::encoding::to_hex;

    fn unlock() -> UnlockRequest {
        UnlockRequest {
            verifier_name: "Workstation".into(),
            volume_name: "cryptroot".into(),
            volume_binding: core::array::from_fn(|index| index as u8),
            credential_id: "desktop-diskUnlock-v1".into(),
            wrapper: vec![9; 60],
        }
    }

    #[test]
    fn unlock_request_has_a_cross_language_vector() {
        assert_eq!(
            to_hex(&unlock().encode()),
            concat!(
                "86016b576f726b73746174696f6e696372797074726f6f745820000102030405",
                "060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f756465736b",
                "746f702d6469736b556e6c6f636b2d7631583c090909090909090909090909",
                "0909090909090909090909090909090909090909090909090909090909090909",
                "09090909090909090909090909090909"
            )
        );
    }

    #[test]
    fn payloads_and_persistent_wrapper_round_trip() {
        let enroll = EnrollRequest {
            verifier_name: "Workstation".into(),
            volume_name: "cryptroot".into(),
            volume_binding: [3; 32],
            disk_key: vec![4; 32],
        };
        assert!(EnrollRequest::decode(&enroll.encode()).unwrap() == enroll);
        let response = EnrollResponse {
            credential_id: "disk-v1".into(),
            wrapper: vec![5; 60],
        };
        assert!(EnrollResponse::decode(&response.encode()).unwrap() == response);
        assert!(UnlockRequest::decode(&unlock().encode()).unwrap() == unlock());
        let answer = UnlockResponse {
            disk_key: vec![6; 32],
        };
        assert!(UnlockResponse::decode(&answer.encode()).unwrap() == answer);
        let stored = WrappedVolumeKey {
            volume_binding: [7; 32],
            credential_id: "disk-v1".into(),
            wrapper: vec![8; 60],
        };
        assert!(WrappedVolumeKey::decode(&stored.encode()).unwrap() == stored);
    }

    #[test]
    fn wrong_sizes_versions_and_shapes_fail_closed() {
        let mut bad = UnlockResponse {
            disk_key: vec![0; 31],
        };
        assert!(bad.validate().is_err());
        bad.disk_key.push(0);
        let mut encoded = bad.encode();
        encoded[1] = 2;
        assert!(UnlockResponse::decode(&encoded).is_err());
        assert!(UnlockRequest::decode(&bad.encode()).is_err());
        let mut trailing = unlock().encode();
        trailing.push(0);
        assert!(UnlockRequest::decode(&trailing).is_err());
    }

    #[test]
    fn application_envelope_accepts_only_the_luks_namespace() {
        for operation in [OPERATION_ENROLL, OPERATION_UNLOCK] {
            let frame = crate::ApplicationFrame {
                protocol_version: crate::PROTOCOL_VERSION,
                kind: crate::ApplicationFrameKind::Request,
                request_id: "request-1".into(),
                session_binding: [0; 32],
                operation: operation.into(),
                issued_at_ms: 1,
                expires_at_ms: 2,
                payload: unlock().encode(),
            };
            frame.validate().unwrap();
        }
    }
}
